/* Loader <-> panel bridge over Cavalry's WebServer / WebClient.
   Both APIs are documented, but this build was written with Cavalry closed, so every call is guarded and a
   failure is not fatal: the panel and the loader each build a JSON they were given, on their own. */
var JZBridge = (function () {
'use strict';
var PORT = 41234, VERSION = 'JIZURA_CV/1';

function hasServer() { return typeof api !== 'undefined' && typeof api.WebServer === 'function'; }
function hasClient() { return typeof api !== 'undefined' && typeof api.WebClient === 'function'; }

/* Panel side: listen for posted assemblies. Returns false when the host has no WebServer. */
var bound = null;
function start(onMessage) {
  if (!hasServer()) return false;
  if (bound) return true;
  var server;
  try {
    server = new api.WebServer();
    if (typeof server.setResultForGet === 'function') server.setResultForGet(VERSION);
    if (typeof server.addCallbackObject === 'function') server.addCallbackObject({
      onPost: function () {
        try {
          var guard = 0;
          while (typeof server.postCount === 'function' && server.postCount() > 0 && guard++ < 16) {
            var post = server.getNextPost();
            var text = post && (post.result != null ? post.result : post.body);
            if (text == null) continue;
            var msg = typeof text === 'string' ? JSON.parse(text) : text;
            if (!msg) continue;
            var assembly = msg.path ? JSON.parse(api.readFromFile(msg.path)) : msg.assembly;
            if (assembly) onMessage(assembly, msg);
          }
        } catch (e) { console.warn('JIZURA bridge: ' + (e && e.message || e)); }
      }
    });
    if (typeof server.listen === 'function') server.listen('localhost', PORT);
    if (typeof server.setHighFrequency === 'function') server.setHighFrequency();
    bound = server;
    return true;
  } catch (e) {
    console.warn('JIZURA bridge: WebServer unavailable (' + (e && e.message || e) + '). Pick the JSON in the panel instead.');
    return false;
  }
}

/* Loader side: send the file path when a panel answers, otherwise return false and let the loader build. */
function handoff(file) {
  if (!hasClient()) return false;
  try {
    var client = new api.WebClient('http://localhost:' + PORT);
    client.get('/get');
    if (typeof client.status === 'function' && client.status() !== 200) return false;
    var body = typeof client.body === 'function' ? String(client.body() || '') : '';
    if (body.indexOf('JIZURA_CV') !== 0) return false;
    client.post('/post', JSON.stringify({ type: 'path', path: file }), 'application/json');
    return typeof client.status !== 'function' || client.status() === 200;
  } catch (e) {
    return false;
  }
}

return { version: VERSION, port: PORT, start: start, handoff: handoff, server: hasServer, client: hasClient };
})();

/* JIZURA CV panel for Cavalry. Install once: Help > Show Scripts Folder, then Window > Scripts > JIZURA CV.
   Picks a .jizura.cavalry.json assembly (written by the JIZURA page) and builds the composition. The JSON
   carries every preset name, so a newer file needs no new script. When Cavalry exposes WebServer the panel
   also accepts a file from JIZURA_CV_Loader.js; when it does not, the button below is the whole workflow. */
(function () {
  if (typeof ui === 'undefined' || typeof api === 'undefined' || typeof JZCavalry === 'undefined') return;

  function folder() {
    try { return api.getFolderFromPath(api.getSceneFilePath() || '') || ''; } catch (error) { return ''; }
  }

  function build(assembly, source) {
    if (!assembly || assembly.format !== 'jizura.cavalry.assembly') throw new Error('JIZURA の JSON ではありません');
    var result = JZCavalry.run(assembly, { componentPath: null, fontOverrides: {}, timingPaths: null });
    var r = result.report || { built: {}, fallback: {}, missing: {}, errors: [] };
    var line = '完了: テキスト ' + (assembly.nodeCount || 0) + ' 項目 / レイヤー ' + result.layerIds.length +
      ' / 正確 ' + Object.keys(r.built).length + ' · 近似 ' + Object.keys(r.fallback).length +
      ' · 未対応 ' + Object.keys(r.missing).length + ' · エラー ' + r.errors.length;
    status.setText(line + (source ? '（' + source + '）' : ''));
    console.log('JIZURA report:\n' + JSON.stringify(r, null, 2));
    return result;
  }

  ui.setTitle('JIZURA CV');
  var status = new ui.Label('JIZURA で書き出した .jizura.cavalry.json を選んでください。');
  var button = new ui.Button('JSON からコンポジションを作る');

  button.onClick = function () {
    var file = api.presentOpenFile(folder(), 'JIZURA Cavalry JSON', 'JIZURA Assembly (*.json)');
    if (!file) return;
    try { build(JSON.parse(api.readFromFile(file))); }
    catch (error) {
      status.setText('失敗: ' + (error && error.message || error));
      console.error('JIZURA: ' + (error && error.stack || error));
    }
  };

  var bridged = typeof JZBridge !== 'undefined' && JZBridge.start(function (assembly) {
    try { build(assembly, 'ローダーから受信'); }
    catch (error) {
      status.setText('失敗: ' + (error && error.message || error));
      console.error('JIZURA: ' + (error && error.stack || error));
    }
  });
  if (bridged) status.setText('パネル受信待ち (localhost:' + JZBridge.port + ')。JSON を選ぶこともできます。');

  ui.add(status);
  ui.add(button);
  ui.addStretch();
  ui.show();
})();

